import{_ as r,o,c as n,h as e,s as t}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"安徽师范大学校园视频下载器2.0版本发布","description":"","frontmatter":{"title":"安徽师范大学校园视频下载器2.0版本发布","date":"2013-03-15 15:30","comments":true,"archives":2013,"tags":["notes"]},"headers":[],"relativePath":"posts/2013-03-15-ahnu-video-downloader/index.md","filePath":"posts/2013/2013-03-15-ahnu-video-downloader.md"}'),s={name:"posts/2013-03-15-ahnu-video-downloader/index.md"};function l(d,a,i,c,p,h){return o(),n("div",null,[...a[0]||(a[0]=[e("p",null,"安师大的校园视频网是个资源不错但软件坑爹的东西. 当然这个服务不是安师大自己研发的,是由沈阳光音网视科技有限公司开发的,应该是学校出钱购买的吧.不过那个坑爹的客户端只给在线观看不给下载, 网页也是完美的兼容 IE6,Javascript 里面也调用了好多微软自己的 ActiveX 控件,所以只能用学校提供的自带的那个客户端浏览和观看视频.",-1),e("p",null,[t("对于这种反人类的做法我当然是很不爽了,客户端的网址栏虽然是不变的,不过是通过重定向的方式访问学校的服务器了吧,通过修改 hosts 我也可以直接在 IE 浏览器中查看,然后查看源代码进行了分析工作.原理其实很简单,就是通过解析服务器上的 XML 文件进行网页的渲染,XML 文件里面记录了服务器上所有的 视频资源和视频的 ID,然后通过一步步的研究直接找到了资源的下载地址.详细的原理请看我 github 上公开的"),e("a",{href:"https://github.com/acgotaku/VideoSearch",target:"_blank",rel:"noreferrer"},"VideoSeach"),t(" 里面的 Function.cs 记录了具体解析过程.")],-1),e("p",null,"通过研究知道了原理便和同学商量这开发个下载器方便大家使用,Win 版本是由同学基于.Net Framework 2.0 开发的,由于我的特殊需求变移植了 web 版本,1.0 版本是在上学期开发并发布的.现在软件使用的用户大概有一万人左右,因为很多学校也用的这个视频服务提供商,我们变提供了配置按钮可以满足 各个学校的需求.不过寒假回来发现下载器不能再下载视频了,我便抽出一晚上时间研究了原因,发现是学校的服务器屏蔽了下载器的功能.手法也很简单使用 User-Agent: Novasoft NetPlayer/4.0 进行屏蔽非官方客户端,知道原因事情就很简单了,伪造 UA 嘛,之前下载器是调用迅雷下载的,现在在里面内置了下载功能.",-1),e("p",null,[t("软件官网: "),e("a",{href:"http://www.icehoney.me",target:"_blank",rel:"noreferrer"},"www.icehoney.me")],-1),e("p",null,[t("百度云盘下载:"),e("a",{href:"http://pan.baidu.com/share/link?shareid=457833&uk=3021310168",target:"_blank",rel:"noreferrer"},"Download")],-1)])])}const f=r(s,[["render",l]]);export{m as __pageData,f as default};
